-- =====================================================================
-- Catalogue Images Responsives — controles bloquants
--
-- Le classeur porte 330 commandes IMAGE. Chaque ecart leve : mieux vaut un
-- import interrompu qu'un catalogue a moitie remplace.
-- =====================================================================

do $ctrl$
declare
  n integer;
  bloquees integer;
begin
  select count(*) into n from public.prompts
   where catalog_version = 'images-responsives';
  if n <> 330 then raise exception 'Attendu 330 cartes mises a jour, trouve %.', n; end if;

  -- Lignes que le controle d'empreinte a refusees : leur payload en base ne
  -- venait pas du classeur, on les a laissees telles quelles.
