bbb248c99244"}, {"ref": "RCI-IMG-324", "sha": "f012c26e8da5e0176dbe7d37d70f6a85a0d0f2a728ec95714967197d1b54fd5d"}, {"ref": "RCI-IMG-325", "sha": "3276336d173afd0122eb9eafd9ee14a0b72079b3d18172405423b96a328b7049"}, {"ref": "RCI-IMG-326", "sha": "da79c37df6819f20bfce05ff51d8bebe76beccb3bc33f894d6389c22dc7e6c2a"}, {"ref": "RCI-IMG-327", "sha": "5eae484085e823ce3e9250c43e8f030dc3b2017ae7ba0c7e341d50ab8982aa1b"}, {"ref": "RCI-IMG-328", "sha": "8f7be2885c94a3e5b8109e4ba9dcef874fe2c15632830a33be02e790404b807a"}, {"ref": "RCI-IMG-329", "sha": "97c4df12ab02e1bdb47dc30fa0a73cc370beb857b88667d965c4ba59164a4a22"}, {"ref": "RCI-IMG-330", "sha": "5cc4e4821ee7851c4504bbc2953ba7600cc30ef1f3e87599f621a8922a99ce40"}]$raccourcia$::jsonb) as e(ref text, sha text)
  join public.prompts p on p.external_ref = e.ref
  join public.prompt_variants v on v.prompt_id = p.id
  join public.prompt_versions pv on pv.variant_id = v.id and pv.is_current
  join public.ai_providers ia on ia.id = v.provider_id and ia.key = 'chatgpt'
  where pv.version_label <> 'images-responsives';
  if bloquees > 0 then
    raise notice '% raccourcis conserves : empreinte differente de celle du classeur.', bloquees;
  end if;

  select count(*) into n from public.prompt_variants v
   join public.prompts p on p.id = v.prompt_id
   where p.mode = 'image' and p.status = 'published'
     and not exists (select 1 from public.prompt_versions pv
                      where pv.variant_id = v.id and pv.is_current);
  if n <> 0 then raise exception '% variantes image sans version courante.', n; end if;

  select count(*) into n from public.prompt_questions q
   join public.prompts p on p.id = q.prompt_id
   where p.mode = 'image' and p.status = 'published';
  if n <> 990 then raise exception 'Attendu 990 questions image, trouve %.', n; end if;

  -- Les visuels ne devaient pas bouger d'un pouce.
  select count(*) into n from public.prompt_media;
  raise notice 'Visuels en base : %.', n;
end $ctrl$;
